import React, { useState } from 'react';
import { Search, SlidersHorizontal } from 'lucide-react';
import './SearchBar.css';

export default function SearchBar({ onSearch, compact = false }) {
  const [filters, setFilters] = useState({ keyword: '', type: '', listingType: '', city: '', minPrice: '', maxPrice: '', bedrooms: '' });
  const [showFilters, setShowFilters] = useState(false);

  const set = (key, val) => setFilters(f => ({ ...f, [key]: val }));

  const handleSubmit = (e) => {
    e.preventDefault();
    onSearch(filters);
  };

  return (
    <form className={`search-bar ${compact ? 'compact' : ''}`} onSubmit={handleSubmit}>
      <div className="search-main">
        <div className="search-input-wrap">
          <Search size={18} className="search-icon" />
          <input
            type="text"
            placeholder="Search by area, suburb, or street name..."
            value={filters.keyword}
            onChange={e => set('keyword', e.target.value)}
            className="search-input"
          />
        </div>
        <select value={filters.listingType} onChange={e => set('listingType', e.target.value)} className="search-select">
          <option value="">Buy or Rent</option>
          <option value="sale">For Sale</option>
          <option value="rental">To Let</option>
        </select>
        <select value={filters.type} onChange={e => set('type', e.target.value)} className="search-select">
          <option value="">Property Type</option>
          <option value="house">House</option>
          <option value="apartment">Apartment</option>
          <option value="commercial">Commercial</option>
          <option value="land">Land</option>
        </select>
        <button type="button" className="btn btn-ghost filter-toggle" onClick={() => setShowFilters(!showFilters)}>
          <SlidersHorizontal size={16} /> Filters
        </button>
        <button type="submit" className="btn btn-accent search-btn">
          <Search size={16} /> Search
        </button>
      </div>

      {showFilters && (
        <div className="search-filters">
          <div className="filter-row">
            <input type="text" placeholder="City" value={filters.city} onChange={e => set('city', e.target.value)} className="form-control" />
            <input type="number" placeholder="Min Price (R)" value={filters.minPrice} onChange={e => set('minPrice', e.target.value)} className="form-control" />
            <input type="number" placeholder="Max Price (R)" value={filters.maxPrice} onChange={e => set('maxPrice', e.target.value)} className="form-control" />
            <select value={filters.bedrooms} onChange={e => set('bedrooms', e.target.value)} className="form-control">
              <option value="">Min Bedrooms</option>
              {[1,2,3,4,5].map(n => <option key={n} value={n}>{n}+</option>)}
            </select>
          </div>
        </div>
      )}
    </form>
  );
}
